+    for (int k = 0; k < kc; ++k) {
+        const __m512 bv = _mm512_maskz_loadu_ps(mask, b + static_cast<std::size_t>(k) * bstride);
+        x0 = _mm512_fmadd_ps(_mm512_set1_ps(a[k]), bv, x0);
